css:
*, ::before, ::after {
	box-sizing: border-box;
}

.login {
	display: block;
	width: 4.99902rem;
	padding: 0.625rem 1.25rem;
	border-radius: 0.625rem;
	border-style: none;
	border-color: currentcolor;
	background-color: #2b6cb0;
	color: #fff;
	font-weight: 600;
	transition: background 0.2s;
	cursor: pointer;
}

.login:hover {
	background-color: #1e4e8c !important;
}

.login {
	transition: 0.2s !important;
}
